def charges_annuelles(apps, schema_editor):
    """Charge ANNUELLE de l'arrêté (art. 5) à la place de l'ancien « service par semestre » ; grades des textes seuls."""
    ParametresHeures = apps.get_model('pfe', 'ParametresHeures')
    for p in ParametresHeures.objects.all():
        anciens = p.grades or {}
        p.grades = {code: {'charge': v['charge'], 'taux': (anciens.get(code) or {}).get('taux') or v['taux']}
                    for code, v in TEXTES.items()}
        p.save(update_fields=['grades'])


